<script>
  /* Enable/Disable Collector Login Access */
  $('#collectorAccessLabel').click(() => {
    const data = {disabled: +$('#collectorAccess')[0].checked};
    $('#loaderB').css('display', 'block');
    $('.error').html('');

    post('/owner/enable_disable', {data}).then(res => {
      res.error ? $('.error').html(res.error) : $('#collectorAccess')[0].checked = res.checked;
      $('#loaderB').hide();
    }).catch(err => {
      $('.error').html('Internal Server Error!');
      $('#loaderB').hide();
    });
  });
</script>